import { Card } from '@app/components';

interface SeoHeroProps {
  pageViews: number; impressions: number; clickRate: number; avgPosition: number
}

export function SeoHero(props: SeoHeroProps) {
  const stats = [
    { label: 'Page Views', value: props.pageViews.toLocaleString() },
    { label: 'Impressions', value: props.impressions.toLocaleString() },
    { label: 'Click Rate', value: props.clickRate.toFixed(1) + '%' },
    { label: 'Avg Position', value: props.avgPosition.toFixed(1) },
  ];
  return (
    <div className="grid grid-cols-2 gap-3 mb-6 sm:grid-cols-4">
      {stats.map(s => (
        <Card key={s.label} variant="default" padding="md">
          <p className="text-xs font-semibold text-text-faint uppercase tracking-wider mb-1">{s.label}</p>
          <p className="text-2xl font-bold text-text">{s.value}</p>
        </Card>
      ))}
    </div>
  );
}
